SINA_SMART["physics1-acid-base"] = {"lecture":"physics1-acid-base","title":"Acid-base balance","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"physics1-acid-base:e0","text":"Arterial pH 7.38-7.42; life-compatible ~7.00-7.80.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-acid-base:e1","text":"pH = −log[H⁺].","topic":"Acids, bases and buffers","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-acid-base:e2","text":"Strong acid: high Ka, low pKa; weak acid: low Ka, high pKa.","topic":"Acids, bases and buffers","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-acid-base:e3","text":"Buffer = weak acid + conjugate base.","topic":"Acids, bases and buffers","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-acid-base:e4","text":"Open buffer: H₂CO₃/HCO₃⁻, pKa 6.1; HCO₃⁻ 24-28 mmol/L; PCO₂ 40 mmHg.","topic":"Acids, bases and buffers","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-acid-base:e5","text":"pH = 6.1 + log[HCO₃⁻]/(0.03·PCO₂) ≈ 6.1 + log 20 = 7.40.","topic":"Acids, bases and buffers","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-acid-base:e6","text":"Closed buffers: phosphate (pKa 6.82), proteins, haemoglobin.","topic":"Acids, bases and buffers","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-acid-base:e7","text":"Acidosis: H⁺ enters cells in exchange for K⁺.","topic":"Disorders and compensation","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-acid-base:e8","text":"Respiratory disorders: PCO₂; metabolic disorders: HCO₃⁻.","topic":"Disorders and compensation","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-acid-base:e9","text":"Lungs compensate in minutes; kidneys in hours-days.","topic":"Disorders and compensation","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1xf1tlr":"a","1yajqys":"a","6rthb7":"a","yuq7w6":"a","1dnphe7":"a","1px7dbz":"a","lfh047":"a","ramd20":"a","1b7j730":"a","ej5t06":"a","1dhg5wy":"a","uc3evt":"a","1lfwe55":"a"},"mapCounts":{"verified":0,"auto":13,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"physics1-acid-base:e0":{"s":0,"u":["Arterial pH 7.38-7.42; life-compatible ~7.00-7.80.","Blood pH must stay within narrow limits: arterial pH 7.38-7.42 (venous 7.36-7.41); the range compatible with life is about 7.00-7.80 . pH = −log[H⁺] , so [H⁺] = 10⁻ᵖᴴ mol/L; neutral 7, acidic 7."],"dp":[]},"physics1-acid-base:e1":{"s":1,"u":["pH = −log[H⁺].","Open system : H₂CO₃/HCO₃⁻ , pKa 6.1 at 37 °C; HCO₃⁻ normally 24-28 mmol/L ; H₂CO₃ is in equilibrium with dissolved CO₂, proportional to arterial PCO₂ (normally 40 ± 3 mmHg ), which the lungs control: Henderson-Hasselbalch: pH = 6.1 + log [HCO₃⁻] / (0.03 × PCO₂) (0.03 mmol/L/mmHg = CO₂ solubility); with 24 mmol/L and 40 mmHg: 6.1 + log(24/1.2) = 6.1 + log 20 ≈ 7.40 .","A strong acid dissociates easily (high Ka, low pKa = −log Ka ); a weak acid stays mostly combined (low Ka, high pKa)."],"dp":[]},"physics1-acid-base:e2":{"s":1,"u":["Strong acid: high Ka, low pKa; weak acid: low Ka, high pKa.","A strong acid dissociates easily (high Ka, low pKa = −log Ka ); a weak acid stays mostly combined (low Ka, high pKa).","A buffer (weak acid + conjugate base) damps pH changes very quickly."],"dp":[]},"physics1-acid-base:e3":{"s":1,"u":["Buffer = weak acid + conjugate base.","A buffer (weak acid + conjugate base) damps pH changes very quickly.","An acid releases H⁺; a base captures H⁺; an acid and its conjugate base form a pair (A ⇌ B + H⁺)."],"dp":[{"h":"Why bicarbonate is the body's most powerful buffer","t":"Its pKa (6.1) is far from blood pH, which would make it a weak closed buffer. What makes it powerful is that it is open: the acid side leaves as CO₂ through the lungs, and the kidneys regenerate bicarbonate. Both terms of the Henderson-Hasselbalch ratio can therefore be adjusted independently, which is how acid-base disorders are compensated. Source: the lecture's open buffer system slides."}]},"physics1-acid-base:e4":{"s":1,"u":["Open buffer: H₂CO₃/HCO₃⁻, pKa 6.1; HCO₃⁻ 24-28 mmol/L; PCO₂ 40 mmHg.","Open system : H₂CO₃/HCO₃⁻ , pKa 6.1 at 37 °C; HCO₃⁻ normally 24-28 mmol/L ; H₂CO₃ is in equilibrium with dissolved CO₂, proportional to arterial PCO₂ (normally 40 ± 3 mmHg ), which the lungs control: Henderson-Hasselbalch: pH = 6.1 + log [HCO₃⁻] / (0.03 × PCO₂) (0.03 mmol/L/mmHg = CO₂ solubility); with 24 mmol/L and 40 mmHg: 6.1 + log(24/1.2) = 6.1 + log 20 ≈ 7.40 ."],"dp":[]},"physics1-acid-base:e5":{"s":1,"u":["pH = 6.1 + log[HCO₃⁻]/(0.03·PCO₂) ≈ 6.1 + log 20 = 7.40.","Open system : H₂CO₃/HCO₃⁻ , pKa 6.1 at 37 °C; HCO₃⁻ normally 24-28 mmol/L ; H₂CO₃ is in equilibrium with dissolved CO₂, proportional to arterial PCO₂ (normally 40 ± 3 mmHg ), which the lungs control: Henderson-Hasselbalch: pH = 6.1 + log [HCO₃⁻] / (0.03 × PCO₂) (0.03 mmol/L/mmHg = CO₂ solubility); with 24 mmol/L and 40 mmHg: 6.1 + log(24/1.2) = 6.1 + log 20 ≈ 7.40 ."],"dp":[]},"physics1-acid-base:e6":{"s":1,"u":["Closed buffers: phosphate (pKa 6.82), proteins, haemoglobin.","Closed systems (total acid + base constant): phosphate (pKa 6.82; HPO₄²⁻/H₂PO₄⁻ = 4 gives pH 7.4; intracellular and renal), proteins (plasma and cells), and haemoglobin , the main red-cell buffer (so blood buffers more than plasma)."],"dp":[]},"physics1-acid-base:e7":{"s":2,"u":["Acidosis: H⁺ enters cells in exchange for K⁺."],"dp":[]},"physics1-acid-base:e8":{"s":2,"u":["Respiratory disorders: PCO₂; metabolic disorders: HCO₃⁻.","Respiratory acidosis : PCO₂ ↑ (hypoventilation); respiratory alkalosis : PCO₂ ↓ (hyperventilation).","Metabolic acidosis : HCO₃⁻ ↓ (acid gain, e.g. ketoacidosis, or bicarbonate loss, e.g. diarrhoea); metabolic alkalosis : HCO₃⁻ ↑ (e.g. vomiting)."],"dp":[]},"physics1-acid-base:e9":{"s":2,"u":["Lungs compensate in minutes; kidneys in hours-days.","Compensation acts on the other term of the ratio: the lungs change PCO₂ within minutes (hyperventilation in metabolic acidosis), the kidneys adjust H⁺ excretion and HCO₃⁻ over hours to days (bicarbonate retention in respiratory acidosis)."],"dp":[]}},"meta":{"1xf1tlr":{"a":"recall","vg":"physics1-acid-base:e0/recall/1"},"1yajqys":{"a":"recall","vg":"physics1-acid-base:e5/recall/1"},"6rthb7":{"a":"recall","vg":"physics1-acid-base:e2/recall/1"},"yuq7w6":{"a":"recall","vg":"physics1-acid-base:e3/recall/1"},"1dnphe7":{"a":"recall","vg":"physics1-acid-base:e6/recall/1"},"1px7dbz":{"a":"recall","vg":"physics1-acid-base:e4/recall/1"},"lfh047":{"a":"recall","vg":"physics1-acid-base:e4/recall/2"},"ramd20":{"a":"relationship","vg":"physics1-acid-base:e4/relationship/1"},"1b7j730":{"a":"recall","vg":"physics1-acid-base:e4/recall/2"},"ej5t06":{"a":"recall","vg":"physics1-acid-base:e6/recall/2"},"1dhg5wy":{"a":"recall","vg":"physics1-acid-base:e8/recall/1"},"uc3evt":{"a":"recall","vg":"physics1-acid-base:e8/recall/2"},"1lfwe55":{"a":"recall","vg":"physics1-acid-base:e8/recall/1"}},"explRev":"9626dd3bdff5"};
